css:
:root {
  --ab-size: 100vmin;
  --ab-top: #74F476;
  --ab-mid: #25D450;
  --ab-bottom: #088D3B;
  --ab-rim: #075A32;
  --ab-ink: #087B37;
}

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;
  background: transparent !important;
  pointer-events: none;
}

.ab-widget, .ab-widget * { box-sizing: border-box; }

.ab-widget {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.ab-button {
  display: block;
  flex: none;
  width: var(--ab-size);
  height: var(--ab-size);
  min-width: 0;
  min-height: 0;
  padding: 0;
  margin: 0;
  overflow: hidden;
  border: 0;
  border-radius: 50%;
  background: transparent;
  appearance: none;
  cursor: pointer;
  pointer-events: auto;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transform: translateY(0) scale(1);
  filter: brightness(1);
  transition: filter 140ms ease, transform 120ms ease;
}

.ab-button.is-red {
  --ab-top: #FF8583;
  --ab-mid: #E53935;
  --ab-bottom: #A6121C;
  --ab-rim: #671B20;
  --ab-ink: #7F151C;
}

.ab-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

.ab-stop-light { stop-color: var(--ab-top); }
.ab-stop-middle { stop-color: var(--ab-mid); }
.ab-stop-dark { stop-color: var(--ab-bottom); }
.ab-core-rim { stroke: var(--ab-rim); }
.ab-octagon { stroke: var(--ab-ink); }

.ab-lettering {
  fill: var(--ab-ink);
  font: 700 57px "Bahnschrift", "DIN Alternate", "Segoe UI", Arial, sans-serif;
  dominant-baseline: middle;
  letter-spacing: 1px;
}

@media (hover: hover) {
  .ab-button:hover { filter: brightness(.93); }
}

.ab-button:active,
.ab-button.is-pressed {
  transform: translateY(2px) scale(.972);
  filter: brightness(.82);
}

.ab-button:focus-visible { outline: 3px solid #0A638F; outline-offset: -12px; }

.ab-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .ab-button { transition: none; }
}

