"use strict";

(function () {
  const RESPONSE_TIMEOUT_MS = 3000;
  const IDLE_RETRY_MS = 500;
  let container = null;
  let button = null;
  let status = null;
  let latestWidget = null;
  let held = false;
  let activePointer = null;
  let activeKey = null;
  let pending = null;
  let observedValue = null;
  let readyToPress = false;
  let lastIdleOffAt = -Infinity;
  const queue = [];

  function writable() {
    return !!(window.WIDGET && window.WIDGET.escritura) &&
      typeof window.escribir === "function";
  }

  function announce(message) {
    if (status) status.textContent = message;
    if (button) button.title = message;
  }

  function colorFromName(widget) {
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim().toLowerCase() : "";
    return name === "rojo" ? "rojo" : "verde";
  }

  function readBool(value) {
    if (value === true || value === 1) return true;
    if (value === false || value === 0) return false;
    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      if (normalized === "true" || normalized === "1") return true;
      if (normalized === "false" || normalized === "0") return false;
    }
    return null;
  }

  function ensureIdleOff() {
    if (!button || held || observedValue !== true || !writable()) return;
    readyToPress = false;
    if ((pending && pending.on === false) || queue.includes(false)) return;
    const now = Date.now();
    if (now - lastIdleOffAt < IDLE_RETRY_MS) return;
    lastIdleOffAt = now;
    enqueue(false); // Inicialización o corrección: inactivo = OFF.
  }

  function update(widget) {
    latestWidget = widget || null;
    if (!button) return;
    observedValue = readBool(widget && widget.value);
    if (!held) readyToPress = observedValue === false;
    const color = colorFromName(widget);
    button.classList.toggle("is-red", color === "rojo");
    button.setAttribute("aria-label", "Pulsador A-B " + color);
    if (held && !writable()) release();
    ensureIdleOff();
    button.setAttribute("aria-disabled", String(!writable() || !readyToPress));
  }

  window.onWidgetUpdate = update;

  function writeValue(on) {
    // El anfitrión puede entregar el tag como BOOL o como entero 0/1.
    const value = latestWidget && typeof latestWidget.value === "number"
      ? (on ? 1 : 0) : on;
    window.escribir(value);
  }

  function pump() {
    if (pending || queue.length === 0) return;
    const command = queue.shift();
    pending = {
      on: command,
      timer: window.setTimeout(function () {
        if (!pending || pending.on !== command) return;
        pending = null;
        announce("Sin confirmación de escritura del PLC");
        // Una liberación pendiente siempre se despacha después del pulso.
        pump();
      }, RESPONSE_TIMEOUT_MS)
    };

    try {
      writeValue(command);
    } catch (error) {
      window.clearTimeout(pending.timer);
      pending = null;
      announce((error && error.message) || "No se pudo escribir en el PLC");
      pump();
    }
  }

  function enqueue(on) {
    queue.push(on);
    pump();
  }

  window.onWidgetEscrito = function (result) {
    if (!pending) return;
    const writtenOff = pending.on === false;
    window.clearTimeout(pending.timer);
    pending = null;
    if (!result || !result.ok) {
      announce((result && result.error) || "El PLC rechazó la escritura");
    } else {
      announce(held ? "Pulsador presionado" : "Pulsador liberado");
      if (writtenOff && !held && observedValue === false) {
        readyToPress = true;
        button.setAttribute("aria-disabled", "false");
      }
    }
    pump();
  };

  function press() {
    if (held || pending || queue.length || !writable() || !readyToPress || observedValue !== false) return false;
    held = true;
    button.classList.add("is-pressed");
    button.setAttribute("aria-pressed", "true");
    enqueue(true); // Press Action: l34\STOP_VENT = 1.
    return true;
  }

  function release() {
    if (!held) return;
    held = false;
    activePointer = null;
    activeKey = null;
    button.classList.remove("is-pressed");
    button.setAttribute("aria-pressed", "false");
    readyToPress = false;
    button.setAttribute("aria-disabled", "true");
    enqueue(false); // Release Action: l34\STOP_VENT = 0.
  }

  function resize() {
    if (!container) return;
    const side = Math.min(container.clientWidth, container.clientHeight);
    if (side > 0) container.style.setProperty("--ab-size", side + "px");
  }

  function initialize() {
    container = document.querySelector(".ab-widget");
    button = document.querySelector(".ab-button");
    status = document.querySelector(".ab-status");
    if (!container || !button) return;

    update(latestWidget || window.WIDGET || null);
    resize();

    button.addEventListener("pointerdown", function (event) {
      if (event.button !== 0 || event.isPrimary === false) return;
      if (!press()) return;
      activePointer = event.pointerId;
      try { button.setPointerCapture(event.pointerId); } catch (_) { /* opcional */ }
      event.preventDefault();
    });

    button.addEventListener("pointerup", function (event) {
      if (activePointer !== null && event.pointerId === activePointer) release();
    });
    button.addEventListener("pointercancel", release);
    button.addEventListener("pointerleave", release);
    button.addEventListener("lostpointercapture", release);

    button.addEventListener("keydown", function (event) {
      if (event.key !== " " && event.key !== "Enter") return;
      event.preventDefault();
      if (event.repeat || activeKey !== null) return;
      if (press()) activeKey = event.key;
    });
    button.addEventListener("keyup", function (event) {
      if (event.key === activeKey) {
        event.preventDefault();
        release();
      }
    });
    button.addEventListener("blur", release);
    window.addEventListener("pointerup", function (event) {
      if (activePointer !== null && event.pointerId === activePointer) release();
    });
    window.addEventListener("blur", release);
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) release();
    });

    if (typeof ResizeObserver !== "undefined") {
      new ResizeObserver(resize).observe(container);
    } else {
      window.addEventListener("resize", resize);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, { once: true });
  } else {
    initialize();
  }
})();
